<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {ElMessageBox} from 'element-plus'
import {mcpApi,type McpServer,type McpServerInput} from '../api'
import {errorMessage} from '../utils'
const servers=ref<McpServer[]>([]),error=ref(''),busy=ref(false),editing=ref(false),id=ref(''),argsText=ref('[]'),credentialsText=ref(''),message=ref('')
const form=ref<McpServerInput>(defaults())
function defaults():McpServerInput{return {name:'',transport:'http',endpoint:'',command:'',args:[],credentials:null,clear_credentials:false,enabled:true,timeout_seconds:20,max_result_chars:12000}}
async function load(){busy.value=true;error.value='';try{servers.value=await mcpApi.list()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
function edit(server?:McpServer){id.value=server?.id||'';form.value=server?{...server,credentials:null,clear_credentials:false}:defaults();argsText.value=JSON.stringify(server?.args||[],null,2);credentialsText.value='';editing.value=true;error.value='';message.value=''}
async function save(){busy.value=true;error.value='';try{const payload={...form.value};payload.args=payload.transport==='stdio'?JSON.parse(argsText.value):[];payload.endpoint=payload.transport==='http'?payload.endpoint:'';payload.command=payload.transport==='stdio'?payload.command:'';payload.credentials=credentialsText.value.trim()?JSON.parse(credentialsText.value):null;if(!Array.isArray(payload.args)||payload.args.some(v=>typeof v!=='string'))throw Error('参数必须是字符串 JSON 数组。');if(payload.credentials&&(typeof payload.credentials!=='object'||Array.isArray(payload.credentials)||Object.values(payload.credentials).some(v=>typeof v!=='string')))throw Error('凭据必须是 JSON 字符串字典。');if(id.value)await mcpApi.edit(id.value,payload);else await mcpApi.add(payload);editing.value=false;credentialsText.value='';message.value='已保存。请连接并发现工具，再到项目助手配置项目授权。';await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function discover(server:McpServer){busy.value=true;error.value='';message.value='';try{const result=await mcpApi.discover(server.id);message.value=`连接成功 · 协议 ${result.protocol_version} · ${result.tools.length} 个工具。目录已更新，需重新保存项目授权。`;await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function remove(server:McpServer){try{await ElMessageBox.confirm(`删除「${server.name}」及项目绑定？历史审计保留，未执行调用会失效。`,'删除 MCP 服务',{type:'warning'});busy.value=true;await mcpApi.remove(server.id);await load()}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorMessage(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><main class="page-content"><div class="page-header"><div><h1>MCP 服务</h1><p>后端作为客户端连接外部服务，再按项目选择允许的工具。</p></div><el-button type="primary" :disabled="busy" @click="edit()">添加服务</el-button></div>
<el-alert title="只添加你信任的服务。stdio 会在本机启动指定程序；HTTP 使用独立凭据。不要把密钥放在命令、参数或 URL 中。连接发现不会调用业务工具。" type="info" :closable="false"/>
<el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="message" :title="message" type="success" :closable="false"/>
<el-button :loading="busy" @click="load">刷新服务</el-button>
<el-empty v-if="!servers.length&&!busy" description="尚未配置 MCP 服务"/>
<el-card v-for="server in servers" :key="server.id" class="mcp-card"><h3>{{server.name}} <el-tag>{{server.enabled?'启用':'禁用'}}</el-tag></h3><p>{{server.transport==='http'?'Streamable HTTP':'stdio'}} · {{server.transport==='http'?server.endpoint:server.command}}</p><p class="field-help">版本 {{server.revision}} · {{server.tools.length}} 个工具 · 凭据名称：{{server.credential_names.join('、')||'无'}}（值不回显）</p><el-button :disabled="busy" @click="edit(server)">编辑/禁用</el-button><el-button :disabled="busy||!server.enabled" @click="discover(server)">连接并发现工具</el-button><el-button type="danger" plain :disabled="busy" @click="remove(server)">删除</el-button><details v-for="tool in server.tools" :key="tool.name"><summary>{{tool.name}}</summary><p>{{tool.description}}</p><pre>{{JSON.stringify(tool.inputSchema,null,2)}}</pre><p class="field-help">远端注解仅供参考，授权分类需由用户判断：{{JSON.stringify(tool.annotations)}}</p></details></el-card>
<el-dialog v-model="editing" :title="id?'编辑 MCP 服务':'添加 MCP 服务'" width="min(650px,95vw)" :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy"><el-form :disabled="busy" label-position="top" @submit.prevent="save"><el-form-item label="服务名称"><el-input v-model="form.name" maxlength="80" aria-label="MCP 服务名称"/></el-form-item><el-form-item label="传输方式"><el-select v-model="form.transport" :disabled="busy" aria-label="MCP 传输方式"><el-option label="Streamable HTTP" value="http"/><el-option label="stdio 本地进程" value="stdio"/></el-select></el-form-item><el-form-item v-if="form.transport==='http'" label="MCP 端点（完整路径，不含 query、凭据或片段）"><el-input v-model="form.endpoint" placeholder="http://127.0.0.1:18021/mcp" aria-label="MCP 端点"/></el-form-item><template v-else><el-form-item label="可执行文件绝对路径"><el-input v-model="form.command" placeholder="/absolute/path/python" aria-label="MCP 可执行文件"/></el-form-item><el-form-item label="独立参数 JSON 数组（不通过 Shell）"><el-input v-model="argsText" type="textarea" :rows="3" aria-label="MCP 参数数组"/></el-form-item></template><el-form-item :label="form.transport==='http'?'HTTP 凭据 JSON：Authorization / X-API-Key / API-Key':'环境变量 JSON（仅传必要变量）'"><el-input v-model="credentialsText" type="textarea" :rows="3" aria-label="MCP 凭据" placeholder='留空保留；新值完整替换，例如 {"Authorization":"Bearer ..."}'/><p class="field-help">配置保存在本机数据库；值不回显。目标或命令变化时需替换或清除凭据。</p><el-checkbox v-model="form.clear_credentials">清除已保存凭据</el-checkbox></el-form-item><el-form-item label="单次操作超时（5–40 秒）"><el-input-number v-model="form.timeout_seconds" :min="5" :max="40"/></el-form-item><el-form-item label="结果字符上限（1000–20000）"><el-input-number v-model="form.max_result_chars" :min="1000" :max="20000" :step="1000"/></el-form-item><el-switch v-model="form.enabled" active-text="启用服务"/><p class="field-help">每次保存会清空已发现目录并使现有授权失效，需重新发现和授权。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/></el-form><template #footer><el-button :disabled="busy" @click="editing=false;credentialsText=''">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存服务</el-button></template></el-dialog>
</main></template>
<style scoped>.mcp-card{margin:16px 0}.mcp-card details{margin-top:12px}.mcp-card pre{white-space:pre-wrap;max-height:260px;overflow:auto}.page-content>.el-alert{margin-bottom:16px}</style>
